{
    public const string Icerik = """
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Şirket Yönetim Merkezi v5</title>
<style>
:root{color-scheme:dark;--bg:#050914;--p:#0b1424;--p2:#101d31;--l:#263a59;--t:#eef5ff;--m:#91a6c2;--g:#45e2a2;--b:#65a9ff;--r:#ff6d7e;--y:#ffd166;--s:0 16px 48px #0008}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:radial-gradient(circle at 10% 0,#10284b 0,transparent 35%),var(--bg);color:var(--t);font-family:Segoe UI,Arial,sans-serif}body{padding:10px}button,input,select{font:inherit}.shell{max-width:2100px;margin:auto}.top{position:sticky;top:5px;z-index:20;display:flex;justify-content:space-between;gap:10px;align-items:center;padding:12px 14px;border:1px solid var(--l);border-radius:15px;background:#091424ed;box-shadow:var(--s)}.brand{font-size:18px;font-weight:950}.brand small{display:block;color:var(--m);font-size:9px;margin-top:3px;font-weight:500}.status,.tabs,.tags,.row{display:flex;gap:7px;align-items:center;flex-wrap:wrap}.status{justify-content:flex-end}.pill,.tag{padding:5px 8px;border:1px solid var(--l);border-radius:999px;background:#0a1628;color:var(--m);font-size:9px}.pill b{color:var(--t)}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--r);margin-right:5px}.dot.ok{background:var(--g);box-shadow:0 0 12px var(--g)}.hidden,[hidden]{display:none!important}.login{max-width:440px;margin:10vh auto;padding:22px;border:1px solid var(--l);border-radius:18px;background:var(--p);box-shadow:var(--s)}button{cursor:pointer;border:0;border-radius:8px;padding:8px 11px;background:var(--g);color:#032018;font-weight:850}.secondary{background:#203653;color:var(--t)}.danger{background:var(--r);color:#fff}.small{font-size:9px;padding:6px 8px}.full{width:100%;margin-top:9px}.tabs{margin:11px 0}.tab{background:#0a1628;color:var(--m);border:1px solid var(--l);border-radius:999px}.tab.active{background:linear-gradient(135deg,var(--g),var(--b));color:#03151c}.banner,.notice{padding:10px;border:1px solid var(--l);border-radius:10px;color:var(--m);margin:10px 0}.banner{border-color:#6d592b;color:var(--y);background:#211d12}.good{color:var(--g)}.bad{color:var(--r)}.warn{color:var(--y)}.metrics{display:grid;grid-template-columns:repeat(6,minmax(120px,1fr));gap:8px}.metric,.item{padding:10px;border:1px solid var(--l);border-radius:11px;background:linear-gradient(180deg,var(--p2),#091423)}.metric span,.sub{display:block;color:var(--m);font-size:8px}.metric b{display:block;margin-top:6px;font-size:16px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.panel{display:grid;gap:10px}.card{padding:12px;border:1px solid var(--l);border-radius:14px;background:linear-gradient(180deg,#101b2eeb,#08101deb);box-shadow:var(--s);overflow:hidden}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.grid4{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}.title{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:9px}.title h2{margin:0;font-size:15px}.item h3{margin:0 0 4px;font-size:13px}.item p{margin:4px 0;color:var(--m);font-size:9px}.row{justify-content:space-between}label{display:block;color:var(--m);font-size:9px}input,select{display:block;width:100%;margin-top:4px;padding:8px;border:1px solid var(--l);border-radius:8px;background:#06111f;color:var(--t)}.form{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;align-items:end;margin-top:8px}.tablewrap{overflow:auto;max-height:720px}table{width:100%;border-collapse:collapse;min-width:1200px;font-size:9px}th{position:sticky;top:0;background:#101c30;color:var(--m);padding:8px;text-align:left;font-size:8px;text-transform:uppercase;border-bottom:1px solid var(--l)}td{padding:8px;border-bottom:1px solid #1b2a41;vertical-align:top}.num{text-align:right}.bar{height:6px;background:#152239;border-radius:99px;overflow:hidden}.bar i{display:block;height:100%;background:linear-gradient(90deg,var(--b),var(--g))}.event,.tx{padding:7px 0;border-bottom:1px solid var(--l);font-size:9px}.tx{display:grid;grid-template-columns:55px 110px 1fr auto;gap:7px}.busy{position:fixed;left:0;right:0;top:0;height:3px;background:linear-gradient(90deg,var(--g),var(--b),#b68cff);transform:scaleX(0);transform-origin:left;z-index:100}.busy.on{transform:scaleX(1)}#toast{position:fixed;right:12px;bottom:12px;max-width:500px;z-index:90;background:#10243b;box-shadow:var(--s)}@media(max-width:1450px){.metrics{grid-template-columns:repeat(4,1fr)}.grid4{grid-template-columns:repeat(2,1fr)}}@media(max-width:900px){body{padding:5px}.top{position:static;flex-direction:column;align-items:flex-start}.status{justify-content:flex-start}.metrics{grid-template-columns:repeat(2,1fr)}.grid,.grid4,.form{grid-template-columns:1fr}}
</style></head><body><div id="busy" class="busy"></div><div class="shell"><header class="top"><div class="brand">ŞİRKET YÖNETİM MERKEZİ v5<small>Kalıcı fiyat ve kapasite · işletim sistemi · protokol · aşırı yük</small></div><div class="status"><span class="pill"><i id="dot" class="dot"></i><b id="conn">BAĞLANTI YOK</b></span><span class="pill">Tick <b id="tick">0</b></span><span class="pill">Panel <b id="panelName">Genel</b></span><span class="pill">Son veri <b id="updated">—</b></span><button id="logout" class="secondary small hidden">Çıkış</button></div></header><section id="loginView" class="login"><h1>Şirket hesabına giriş</h1><p class="sub">Kod sunucuda yazılır; motor kalıcı ticari ve dağıtım verisinin otoritesidir.</p><label>Kullanıcı adı<input id="username"></label><label>Parola<input id="password" type="password"></label><button id="login" class="full">Giriş yap</button><div id="loginMsg" class="notice">Geçici hesap bilgileri motor konsolunda görünür.</div></section><main id="app" class="hidden"><div class="banner"><b>Zorunlu dağıtım:</b> İşletim sistemi ürünü aktif protokol ister. Diğer her uygulama aktif bir işletim sistemi ve o sistemle ortak protokol seçmeden pasif kalır.</div><section id="metrics" class="metrics"></section><nav id="tabs" class="tabs"><button class="tab active" data-panel="overview">Genel</button><button class="tab" data-panel="services">Hizmetler & Kapasite</button><button class="tab" data-panel="products">Ürünler & Dağıtım</button><button class="tab" data-panel="infra">Altyapı Sınırları</button><button class="tab" data-panel="bank">Banka</button><button class="tab" data-panel="protocols">Protokoller</button><button class="tab" data-panel="contracts">Sözleşmeler</button><button class="tab" data-panel="account">Hesap</button></nav><section id="overview" class="panel"></section><section id="services" class="panel" hidden></section><section id="products" class="panel" hidden></section><section id="infra" class="panel" hidden></section><section id="bank" class="panel" hidden></section><section id="protocols" class="panel" hidden></section><section id="contracts" class="panel" hidden></section><section id="account" class="panel" hidden></section></main></div><div id="toast" class="notice hidden"></div>
<script>
'use strict';const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],money=v=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:2}).format(Number(v||0)),num=v=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:2}).format(Number(v||0)),int=v=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:0}).format(Number(v||0)),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const S={d:null,active:'overview',loading:false,busy:false,timer:null,pending:null,drafts:new Map(),toastTimer:null};
const field=(k,v,t='number',a='')=>`<input data-key="${esc(k)}" type="${t}" value="${esc(S.drafts.has(k)?S.drafts.get(k):v??'')}" ${a}>`;const sel=(k,v,opts)=>{const x=String(S.drafts.has(k)?S.drafts.get(k):v??'');return `<select data-key="${esc(k)}">${opts.map(o=>`<option value="${esc(o[0])}" ${String(o[0])===x?'selected':''}>${esc(o[1])}</option>`).join('')}</select>`};
function panel(id){const t=document.getElementById(id)||$('#overview');S.active=t.id;$$('.panel').forEach(p=>p.hidden=p!==t);$$('.tab').forEach(b=>b.classList.toggle('active',b.dataset.panel===t.id));$('#panelName').textContent=document.querySelector(`.tab[data-panel="${t.id}"]`)?.textContent||t.id;history.replaceState(null,'',`#${t.id}`)}$('#tabs').addEventListener('click',e=>{const b=e.target.closest('[data-panel]');if(b){e.preventDefault();panel(b.dataset.panel)}});
function editing(){return S.busy||!!document.activeElement?.matches('input,select,textarea')}function toast(t,ok=true){const e=$('#toast');clearTimeout(S.toastTimer);e.textContent=t;e.className=`notice ${ok?'good':'bad'}`;e.classList.remove('hidden');S.toastTimer=setTimeout(()=>e.classList.add('hidden'),5000)}async function req(path,body){const r=await fetch(path,{method:body===undefined?'GET':'POST',cache:'no-store',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});let d;try{d=await r.json()}catch{d={basarili:false,aciklama:'Yanıt okunamadı.'}}if(!r.ok||d.basarili===false)throw new Error(d.aciklama||`HTTP ${r.status}`);return d}
function showApp(){$('#loginView').classList.add('hidden');$('#app').classList.remove('hidden');$('#logout').classList.remove('hidden');panel(location.hash.slice(1)||'overview')}async function login(){try{const r=await req('/api/giris',{kullaniciAdi:$('#username').value,parola:$('#password').value});showApp();toast(r.aciklama);await refresh(true);poll()}catch(e){$('#loginMsg').textContent=e.message;$('#loginMsg').className='notice bad'}}async function logout(){try{await req('/api/cikis',{})}catch{}location.reload()}function poll(){clearInterval(S.timer);S.timer=setInterval(()=>refresh(false),1000)}async function refresh(force=false){if(S.loading)return;S.loading=true;try{const d=await req(`/api/durum?t=${Date.now()}`);S.d=d;$('#dot').classList.add('ok');$('#conn').textContent='CANLI';$('#tick').textContent=d.tickNumarasi||0;$('#updated').textContent=new Date().toLocaleTimeString('tr-TR');renderMetrics(d);if(force||!editing()){S.pending=null;renderAll(d)}else S.pending=d}catch(e){$('#dot').classList.remove('ok');$('#conn').textContent='HATA';if(e.message.includes('Oturum'))location.reload()}finally{S.loading=false}}
function renderMetrics(d){const s=d.sirket||{},i=d.isletim||{},k=d.kapasiteOzeti||{},l=d.ekosistem?.altyapiSinirlari||{};const a=[['Kasa',money(s.kasa)],['Şirket değeri',money(i.sirketDegeri)],['Hizmet kapasitesi',int(k.toplamEszamanliIslemKapasitesi)],['Güvenli işlem sınırı',int(l.guvenliEszamanliIslemSiniri)],['Uygulama kapasitesi',int(k.toplamUygulamaKullaniciKapasitesi)],['Güvenli kullanıcı sınırı',int(l.guvenliAktifKullaniciSiniri)],['Aktif kullanıcı',int(k.toplamAktifKullanici)],['Birleşik yük',`%${num((l.birlesikYukOrani||0)*100)}`],['Operasyon riski',num(i.operasyonRiski)],['Teknik borç',num(i.teknikBorc)],['Bakım baskısı',num(i.bakimBaskisi)],['Borç',money(i.toplamBorc)]];$('#metrics').innerHTML=a.map(x=>`<div class="metric"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}
function renderAll(d){overview(d);services(d);products(d);infra(d);bank(d);protocols(d);contracts(d);account(d);panel(S.active)}
function overview(d){const s=d.sirket||{},i=d.isletim||{},l=d.ekosistem?.altyapiSinirlari||{},events=(i.sonOlaylar||[]).map(o=>`<div class="event"><div class="row"><b class="${o.olumlu?'good':'bad'}">${esc(o.baslik)}</b><span>T${o.tickNumarasi}</span></div><p>${esc(o.aciklama)}</p></div>`).join('')||'<div class="notice">Olay yok.</div>',tx=(i.sonIslemler||[]).map(x=>`<div class="tx"><span>T${x.tickNumarasi}</span><b>${esc(x.islemTuru)}</b><span>${esc(x.aciklama)}</span><strong class="${Number(x.tutar)>=0?'good':'bad'}">${money(x.tutar)}</strong></div>`).join('')||'<div class="notice">İşlem yok.</div>';$('#overview').innerHTML=`<div class="grid"><div class="card"><div class="title"><h2>Altyapı sağlığı</h2><span class="tag ${l.durum==='rahat'?'good':l.durum==='kritik'?'bad':'warn'}">${esc(l.durum||'—')}</span></div><div class="grid4">${[['Aktif iş',int(l.mevcutAktifIs)],['Kuyruk',int(l.kuyrukUzunlugu)],['İşlem yükü',`%${num((l.islemYukOrani||0)*100)}`],['Kullanıcı yükü',`%${num((l.kullaniciYukOrani||0)*100)}`],['Gecikme baskısı',num(l.gecikmeBaskisi)],['Kod kalitesi',num(s.kodKalitesiPuani)],['Performans',num(s.performansPuani)],['Güvenlik',num(s.guvenlikPuani)]].map(x=>`<div class="item"><p>${x[0]}</p><b>${x[1]}</b></div>`).join('')}</div></div><div class="card"><div class="title"><h2>Dinamik olaylar</h2><span class="tag warn">İyi şirket de olay yaşayabilir</span></div>${events}</div></div><div class="card"><div class="title"><h2>Kalıcı işlemler</h2></div>${tx}</div>`}
function serviceList(){return S.d?.kodTabanliYayinlar?.hizmetler||[]}function services(d){const list=serviceList();$('#services').innerHTML=`<div class="card"><div class="title"><div><h2>Hizmetler ve gerçek işlem kapasitesi</h2><span class="sub">Etkin = ilk sunucu değeri + satın alınan + yatırım bonusu</span></div></div><div class="tablewrap"><table><thead><tr><th>Hizmet</th><th>Fiyat</th><th>İlk fiyat</th><th class="num">Baz</th><th class="num">Satın</th><th class="num">Yatırım</th><th class="num">Etkin</th><th>Durum</th><th>Kapasite al</th><th>İşlem</th></tr></thead><tbody>${list.map(h=>{const id=`${h.hizmetKimligi}@${h.hizmetSurumu}`;return `<tr><td><b>${esc(h.hizmetKimligi)}</b><span class="sub">v${esc(h.hizmetSurumu)}</span></td><td>${field(`svc:${id}:price`,h.birimFiyat,'number','min="0.01" step="0.01"')}</td><td>${money(h.sunucuDefaultFiyat)}</td><td class="num">${int(h.bazKapasite)}</td><td class="num good">${int(h.satinAlinanKapasite)}</td><td class="num warn">${int(h.yatirimKapasiteBonusu)}</td><td class="num"><b>${int(h.etkinKapasite)}</b></td><td class="${h.aktif?'good':'bad'}">${h.aktif?'AKTİF':'PASİF'}</td><td>${field(`svc:${id}:cap`,1,'number','min="1" max="500"')}<button class="small secondary" data-action="service-cap" data-id="${esc(id)}">Al</button></td><td><button class="small" data-action="service-price" data-id="${esc(id)}">Fiyat</button> <button class="small ${h.aktif?'danger':'secondary'}" data-action="service-toggle" data-id="${esc(id)}">${h.aktif?'Kapat':'Aç'}</button></td></tr>`}).join('')}</tbody></table></div></div>`}
function distributionMap(d){return new Map((d.ekosistem?.dagitimAyarlari||[]).map(x=>[x.urunKimligi,x.ayar||{}]))}function osOptions(d){return [['','İşletim sistemi seç']].concat((d.ekosistem?.isletimSistemleri||[]).map(x=>[x.uygulamaKimligi,`${x.uygulamaAdi} · ${x.sirketAdi} · ${int(x.aktifMusteriSayisi)}/${int(x.kullaniciKapasitesi)}`]))}function protocolOptions(d){const own=(d.kodTabanliYayinlar?.protokoller||[]).filter(x=>x.piyasada).map(x=>[x.protokol?.protokolKimligi,`${x.protokol?.protokolAdi} (kendi)`]),market=(d.protokoller||[]).map(x=>[x.protokolKimligi,`${x.protokolAdi} (piyasa)`]);const m=new Map([['','Protokol seç'],...own,...market]);return [...m.entries()]}
function products(d){const apps=d.kodTabanliYayinlar?.uygulamalar||[],ps=d.isletim?.urunler||[],dm=distributionMap(d),os=osOptions(d),protos=protocolOptions(d);$('#products').innerHTML=`<div class="card"><div class="title"><div><h2>Kodlanan ürünler</h2><span class="sub">Yeni ürün türleri serbesttir; gerçek hizmetler doğrulanır.</span></div></div>${apps.map(x=>appCard(x)).join('')||'<div class="notice">Manifest yok.</div>'}</div><div class="card"><div class="title"><div><h2>Piyasadaki ürünler ve zorunlu dağıtım</h2><span class="sub">Mevcut ürün geçmişi korunur; eksik OS/protokol ürünü pasif kalır.</span></div></div>${ps.map(p=>productCard(p,dm.get(p.urunKimligi)||{},os,protos)).join('')||'<div class="notice">Ürün yok.</div>'}</div>`}
function appCard(x){const a=x.uygulama||{},v=x.dogrulama||{},id=a.uygulamaKimligi;return `<div class="item" style="margin-bottom:8px"><div class="row"><div><h3>${esc(a.uygulamaAdi)} <span class="tag">${esc(a.urunTuru||'uygulama')}</span></h3><p>${esc(a.aciklama)}</p></div><span class="tag ${v.gecerli?'good':'bad'}">${v.gecerli?'TEKNİK GEÇERLİ':'EKSİK'}</span></div>${x.piyasada?`<div class="notice good">Piyasada · ${esc(x.urunKimligi)}</div>`:`<div class="form"><label>Model${sel(`app:${id}:model`,'abonelik',[['abonelik','Abonelik'],['kullanim','Kullanım'],['freemium','Freemium'],['lisans','Lisans'],['tek-seferlik','Tek seferlik']])}</label><label>Abonelik${field(`app:${id}:sub`,25,'number','min="0"')}</label><label>Kullanım${field(`app:${id}:use`,0,'number','min="0"')}</label><button data-action="app-publish" data-id="${esc(id)}" ${!v.gecerli?'disabled':''}>Piyasaya aç</button></div>`}</div>`}
function productCard(p,a,os,protos){const id=p.urunKimligi,isOS=(p.urunTuru==='isletim-sistemi'),occ=Number(p.kullaniciKapasitesi)>0?Number(p.aktifKullaniciSayisi)*100/Number(p.kullaniciKapasitesi):0;return `<div class="item" style="margin-bottom:8px"><div class="row"><div><h3>${esc(p.urunAdi)} <span class="tag">${esc(p.urunTuru||p.kategori)}</span></h3><p>${int(p.aktifKullaniciSayisi)} / ${int(p.kullaniciKapasitesi)} kullanıcı · Doluluk %${num(occ)}</p></div><span class="tag ${p.aktif?'good':'bad'}">${p.aktif?'AKTİF':'PASİF'}</span></div><div class="bar"><i style="width:${Math.min(100,occ)}%"></i></div><div class="tags"><span class="tag ${a.uyumlu?'good':'bad'}">${esc(a.uyumDurumu||'Yapılandırılmadı')}</span><span class="tag warn">Yük %${num((a.sonYukOrani||0)*100)}</span>${a.sonDuraksatmaNedeni?`<span class="tag bad">${esc(a.sonDuraksatmaNedeni)}</span>`:''}</div><div class="form"><label>İşletim sistemi${isOS?'<input value="Kendisi işletim sistemi" disabled>':sel(`dist:${id}:os`,a.isletimSistemiKimligi||'',os)}</label><label>Bağlantı protokolü${sel(`dist:${id}:proto`,a.baglantiProtokoluKimligi||'',protos)}</label><label>İstenen durum${sel(`dist:${id}:active`,String(a.elleAktifOlmasiIsteniyor??p.aktif),[['true','Aktif'],['false','Pasif']])}</label><button data-action="distribution" data-id="${esc(id)}">Dağıtımı kaydet</button></div><div class="form"><label>Abonelik${field(`prd:${id}:sub`,p.abonelikUcreti,'number','min="0"')}</label><label>Kullanım${field(`prd:${id}:use`,p.kullanimBasinaUcret,'number','min="0"')}</label><label>Kapasite ekle${field(`prd:${id}:cap`,100,'number','min="50" max="100000"')}</label><div><button class="small" data-action="product-save" data-id="${esc(id)}">Fiyatı kaydet</button> <button class="small secondary" data-action="product-cap" data-id="${esc(id)}">Kapasite al</button></div></div></div>`}
function infra(d){const l=d.ekosistem?.altyapiSinirlari||{},list=d.yatirimMagazasi||[];$('#infra').innerHTML=`<div class="card"><div class="title"><h2>Gerçek sunucu ve altyapı sınırları</h2><span class="tag ${l.durum==='rahat'?'good':l.durum==='kritik'?'bad':'warn'}">${esc(l.durum||'—')}</span></div><div class="grid4">${[['Toplam hizmet kapasitesi',int(l.toplamHizmetKapasitesi)],['Güvenli eşzamanlı işlem',int(l.guvenliEszamanliIslemSiniri)],['Aktif iş',int(l.mevcutAktifIs)],['Kuyruk',int(l.kuyrukUzunlugu)],['Toplam app kapasitesi',int(l.toplamUygulamaKapasitesi)],['Güvenli aktif kullanıcı',int(l.guvenliAktifKullaniciSiniri)],['Aktif kullanıcı',int(l.mevcutAktifKullanici)],['Birleşik yük',`%${num((l.birlesikYukOrani||0)*100)}`]].map(x=>`<div class="item"><p>${x[0]}</p><b>${x[1]}</b></div>`).join('')}</div></div><div class="card"><div class="title"><div><h2>Yatırımlar</h2><span class="sub">Kod kalitesi ve puanlar güvenli sınırı az miktarda etkiler; donanım ve kapasitenin yerini tutmaz.</span></div></div><div class="grid4">${list.map(x=>`<div class="item"><h3>${esc(x.ad)}</h3><p>${esc(x.aciklama)}</p><div class="tags"><span class="tag good">Seviye ${int(x.seviye)}/${int(x.azamiSeviye)}</span><span class="tag warn">${money(x.tickBakimGideri)}/tick</span></div><div class="row"><b>${money(x.sonrakiMaliyet)}</b><button class="small" data-action="investment" data-id="${esc(x.yatirimTuru)}">Satın al</button></div></div>`).join('')}</div></div>`}
function bank(d){const packs=d.krediPaketleri||[],loans=d.isletim?.krediler||[];$('#bank').innerHTML=`<div class="grid"><div class="card"><div class="title"><h2>Kredi paketleri</h2></div>${packs.map(p=>`<div class="item" style="margin-bottom:8px"><h3>${esc(p.ad)}</h3><p>${money(p.asgariTutar)}–${money(p.azamiTutar)} · Not ≥ ${int(p.asgariKrediNotu)}</p><label>Tutar${field(`loan:${p.krediTuru}`,p.asgariTutar,'number',`min="${p.asgariTutar}" max="${p.azamiTutar}"`)}</label><button class="full" data-action="loan" data-id="${esc(p.krediTuru)}">Kredi çek</button></div>`).join('')}</div><div class="card"><div class="title"><h2>Mevcut krediler</h2></div>${loans.map(l=>`<div class="item"><b>${esc(l.krediTuru)}</b><p>Kalan ${money(l.kalanBorc)} · Taksit ${money(l.taksitTutari)} · Gecikme ${int(l.gecikmeSayisi)}</p></div>`).join('')||'<div class="notice">Kredi yok.</div>'}</div></div>`}
function protocols(d){const own=d.kodTabanliYayinlar?.protokoller||[],market=d.protokoller||[];$('#protocols').innerHTML=`<div class="grid"><div class="card"><div class="title"><h2>Kodlanan protokoller</h2></div>${own.map(x=>{const p=x.protokol||{},id=`${p.protokolKimligi}@${p.surum}`;return `<div class="item"><div class="row"><b>${esc(p.protokolAdi)} v${esc(p.surum)}</b><span class="tag ${x.gecerli?'good':'bad'}">${x.gecerli?'GEÇERLİ':'EKSİK'}</span></div>${x.piyasada?'<div class="notice good">Piyasada</div>':`<div class="form"><label>Lisans${sel(`proto:${id}:model`,'acik',[['acik','Açık'],['tek-seferlik','Tek seferlik'],['abonelik','Abonelik'],['karma','Karma']])}</label><label>Benimseme${field(`proto:${id}:adopt`,0)}</label><label>Tick lisansı${field(`proto:${id}:tick`,0)}</label><button data-action="protocol-publish" data-id="${esc(id)}">Yayınla</button></div>`}</div>`}).join('')||'<div class="notice">Protokol yok.</div>'}</div><div class="card"><div class="title"><h2>Piyasa protokolleri</h2></div>${market.map(p=>`<div class="item"><div class="row"><b>${esc(p.protokolAdi)} v${esc(p.surum)}</b><button class="small" data-action="protocol-adopt" data-id="${esc(p.protokolKimligi)}">Benimse</button></div><p>${money(p.benimsemeBedeli)} + ${money(p.tickLisansBedeli)}/tick</p></div>`).join('')||'<div class="notice">Piyasa protokolü yok.</div>'}</div></div>`}
function contracts(d){const offers=d.sozlesmeTeklifleri||[],active=d.isletim?.sozlesmeler||[];$('#contracts').innerHTML=`<div class="grid"><div class="card"><div class="title"><h2>Açık SLA teklifleri</h2></div>${offers.map(o=>`<div class="item"><div class="row"><div><b>${esc(o.baslik)}</b><p>${esc(o.kategori)} · Kapasite ${int(o.gerekliKapasite)}</p></div><button class="small" data-action="contract" data-id="${esc(o.teklifKimligi)}">Kabul et</button></div></div>`).join('')||'<div class="notice">Teklif yok.</div>'}</div><div class="card"><div class="title"><h2>Sözleşmeler</h2></div>${active.map(s=>`<div class="item"><b>${esc(s.baslik)}</b><p>Başarı ${int(s.basariliTickSayisi)} · İhlal ${int(s.ihlalSayisi)} · Kapasite ${int(s.gerekliKapasite)}</p></div>`).join('')||'<div class="notice">Sözleşme yok.</div>'}</div></div>`}
function account(d){const i=d.isletim||{};$('#account').innerHTML=`<div class="grid"><div class="card"><h2>Parola değiştir</h2><label>Mevcut${field('account:old','', 'password')}</label><label>Yeni${field('account:new','', 'password')}</label><button class="full" data-action="password">Değiştir</button></div><div class="card"><h2>Risk özeti</h2><div class="grid4">${[['Operasyon',num(i.operasyonRiski)],['Teknik borç',num(i.teknikBorc)],['Bakım baskısı',num(i.bakimBaskisi)],['Ödenemeyen',money(i.odenemeyenGider)],['Temerrüt',int(i.temerrutSayisi)],['Kredi notu',int(i.krediNotu)],['Gider',money(i.toplamIsletmeGideri)],['Yatırım',money(i.toplamYatirimHarcamasi)]].map(x=>`<div class="item"><p>${x[0]}</p><b>${x[1]}</b></div>`).join('')}</div></div></div>`}
function val(k){const e=document.querySelector(`[data-key="${CSS.escape(k)}"]`);return e?e.value:(S.drafts.get(k)??'')}function nval(k){const x=Number(val(k));if(!Number.isFinite(x))throw new Error('Sayısal değer geçersiz.');return x}function findService(id){const h=serviceList().find(x=>`${x.hizmetKimligi}@${x.hizmetSurumu}`===id);if(!h)throw new Error('Hizmet bulunamadı.');return h}function findProduct(id){const p=(S.d?.isletim?.urunler||[]).find(x=>x.urunKimligi===id);if(!p)throw new Error('Ürün bulunamadı.');return p}
async function run(b,job){if(S.busy)return;S.busy=true;$('#busy').classList.add('on');const old=b.textContent;b.disabled=true;b.textContent='İşleniyor…';try{const r=await job();toast(r.aciklama||'Tamamlandı.');await refresh(true)}catch(e){toast(e.message,false)}finally{S.busy=false;b.disabled=false;b.textContent=old;$('#busy').classList.remove('on')}}async function action(b){const a=b.dataset.action,id=b.dataset.id||'';await run(b,async()=>{if(a==='service-price'){const h=findService(id);return req('/api/hizmet/fiyat',{hizmetKimligi:h.hizmetKimligi,hizmetSurumu:h.hizmetSurumu,yeniFiyat:nval(`svc:${id}:price`)})}if(a==='service-toggle'){const h=findService(id);return req('/api/hizmet/durum',{hizmetKimligi:h.hizmetKimligi,hizmetSurumu:h.hizmetSurumu,aktif:!h.aktif})}if(a==='service-cap'){const h=findService(id);return req('/api/hizmet/kapasite',{hizmetKimligi:h.hizmetKimligi,hizmetSurumu:h.hizmetSurumu,eklenecekKapasite:nval(`svc:${id}:cap`)})}if(a==='app-publish')return req('/api/uygulama/yayinla',{uygulamaKimligi:id,fiyatlandirmaModeli:val(`app:${id}:model`),abonelikUcreti:nval(`app:${id}:sub`),kullanimBasinaUcret:nval(`app:${id}:use`)});if(a==='distribution')return req('/api/uygulama/dagitim',{urunKimligi:id,isletimSistemiKimligi:val(`dist:${id}:os`),baglantiProtokoluKimligi:val(`dist:${id}:proto`),aktif:val(`dist:${id}:active`)==='true'});if(a==='product-save'){const p=findProduct(id);return req('/api/uygulama/guncelle',{urunKimligi:id,abonelikUcreti:nval(`prd:${id}:sub`),kullanimBasinaUcret:nval(`prd:${id}:use`),aktif:p.aktif})}if(a==='product-cap')return req('/api/uygulama/kapasite',{urunKimligi:id,eklenecekKapasite:nval(`prd:${id}:cap`)});if(a==='investment')return req('/api/yatirim',{yatirimTuru:id});if(a==='loan')return req('/api/kredi',{krediTuru:id,tutar:nval(`loan:${id}`)});if(a==='protocol-publish'){const at=id.lastIndexOf('@');return req('/api/protokol/yayinla',{protokolKimligi:id.slice(0,at),surum:id.slice(at+1),lisansModeli:val(`proto:${id}:model`),benimsemeBedeli:nval(`proto:${id}:adopt`),tickLisansBedeli:nval(`proto:${id}:tick`)})}if(a==='protocol-adopt')return req('/api/protokol/benimse',{protokolKimligi:id});if(a==='contract')return req('/api/sozlesme/kabul',{teklifKimligi:id});if(a==='password')return req('/api/parola',{eskiParola:val('account:old'),yeniParola:val('account:new')});throw new Error('Bilinmeyen işlem.')})}
document.addEventListener('input',e=>{if(e.target?.dataset?.key)S.drafts.set(e.target.dataset.key,e.target.value)});document.addEventListener('change',e=>{if(e.target?.dataset?.key)S.drafts.set(e.target.dataset.key,e.target.value)});document.addEventListener('focusout',()=>setTimeout(()=>{if(S.pending&&!editing()){const d=S.pending;S.pending=null;renderAll(d)}},120));document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b){e.preventDefault();action(b)}});$('#login').addEventListener('click',login);$('#password').addEventListener('keydown',e=>{if(e.key==='Enter')login()});$('#logout').addEventListener('click',logout);req('/api/durum').then(()=>{showApp();refresh(true);poll()}).catch(()=>{});panel(location.hash.slice(1)||'overview');
</script></body></html>
""";
}
